export type NodeMode         = "adversary" | "domestic";
export type NodeCategory     = "mining" | "energy" | "semiconductor" | "military" | "port" | "cyber" | "nuclear" | "financial" | "water" | "rail" | "chemical" | "aerospace" | "chokepoint";
export type NodeRelationship = "allied" | "partner" | "neutral" | "hostile";

export interface GlobeNode {
  id:           string;
  name:         string;
  lat:          number;
  lng:          number;
  country:      string;
  countryCode:  string;
  mode:         NodeMode;
  category:     NodeCategory;
  type:         string;
  description:  string;
  coordinates:  string;
  mapsUrl:      string;
  risk:          number;        // 0-1  higher = more critical
  relationship?: NodeRelationship; // if absent, derive from COUNTRY_RELATIONSHIP
  isTerminal?:   boolean;
}

export interface GlobeEdge {
  from: string;
  to:   string;
  weight: number;
}

